"use strict";(self.webpackChunk_otw_web_docusaurus=self.webpackChunk_otw_web_docusaurus||[]).push([[4753],{7781(e){e.exports=JSON.parse('{"title":"Tanstack-Query \ub354 \uc798 \uc4f0\uae30","date":"2024-04-17","coverUrl":null,"html":"<h2 data-notion-block-id=\\"23c8bcce-cdaa-47c1-80c9-74eb978f9c1e\\" id=\\"23c8bcce-cdaa-47c1-80c9-74eb978f9c1e\\">Tanstack-Query \ub354 \uc798 \uc4f0\uae30</h2><a href=\\"https://tanstack.com/query/v5/docs/framework/react/guides/render-optimizations\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://tanstack.com/query/v5/docs/framework/react/guides/render-optimizations</a><a href=\\"https://www.teemutaskula.com/blog/exploring-query-suspense\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://www.teemutaskula.com/blog/exploring-query-suspense</a><p data-notion-block-id=\\"532a89ae-f97c-44b7-97cc-225e7d9c0cbf\\"><b>\uc2ec\uc724\uc12d</b>: \uc11c\ubc84 \uc0c1\ud0dc \uad00\ub9ac\ub97c Tanstack query\uc5d0 \uc704\uc784\ud558\ub294 \uac83\uc73c\ub85c \uc27d\uac8c \ud6a8\uc728\uc801\uc73c\ub85c \ub80c\ub354\ub9c1 \ucd5c\uc801\ud654\ub97c \uc774\ub918\uc9c0\ub9cc \uc774\ubbf8 \ub108\ubb34 \ub9ce\uc740 \uc0c1\ud0dc\ub97c \uad00\ub9ac\ud558\uace0 \uc788\uc5b4 \ub354 \ucd5c\uc801\ud654\uac00 \ud544\uc694\ud55c \uc0ac\ub78c\ub4e4\uc774\ub098, \uc0ac\uc18c\ud558\uc9c0\ub9cc \ubd88\ud3b8\ud55c UX\ub97c \uc81c\uacf5\ud558\ub294 \uac83\uc744 \ub9c9\uace0\uc790 \ud558\ub294 \uc0ac\ub78c\ub4e4\uc5d0\uac8c \uc870\uc5b8\ud558\ub294 \uae00\uc785\ub2c8\ub2e4. \ub458 \ub2e4 hook\uc5d0 \ub123\ub294 \uc18d\uc131\uc744 \uc5b4\ub5bb\uac8c \uc798 \ub123\uc744 \uac83\uc778\uc9c0\ub97c \uc0dd\uac01\ud574\ubcf4\uac8c \ud558\ub294 \uae00\uc774\uae30 \ub54c\ubb38\uc5d0 Tanstack-query\ub97c \uc4f0\ub294 \uc0ac\ub78c\uc740 \ubb34\uc870\uac74 \ubcf4\uc2dc\uae38 \ubc14\ub78d\ub2c8\ub2e4.</p><p data-notion-block-id=\\"7a4bc0b0-9470-477a-a13c-61207fd3d426\\"><b>\uae40\ub300\uad00</b>: \uc704\uc758 \ucd5c\uc801\ud654 \uae30\ubc95 5\uac1c\uc5d0\uc11c React-Query\uac00 \ube44\ub3d9\uae30 \ucc98\ub9ac\uc5d0 \uac15\ub825\ud55c \ub3c4\uad6c\uc778\uc9c0\ub97c \uc54c\uac8c \ud574\uc90d\ub2c8\ub2e4. \ud2b9\ud788\ub098, <code>select</code> \uc640 \uba54\ubaa8\uc774\uc81c\uc774\uc158\uc744 \ud63c\ud569\ud574\uc11c \uc4f0\ub294 \uc608\uc81c\ub294 useEffect\uc640 \uac19\uc740 \uc120\ud0dd\uc801 \ub80c\ub354\ub9c1\uc5d0 \ud65c\uc6a9\ud560 \uc218 \uc788\uc9c0 \uc54a\uc744\uae4c \ud569\ub2c8\ub2e4. \ube44\ub3d9\uae30 \uad00\ub828 \uae30\ub2a5\uc5d0\uc11c \uac15\ub825\ud55c \ub3c4\uad6c\uc774\uba70 \uc5b4\ub290 \ubd80\ubd84\uc774 \uc88b\uc740 \uc9c0 \uae00\uc744 \ud1b5\ud574 \ub354 \uc774\ud574\ud558\uba74 \uc88b\uc744 \uac83 \uac19\uc2b5\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"83a9e1d2-a2db-4fa2-9f23-deefb811a4ba\\" id=\\"83a9e1d2-a2db-4fa2-9f23-deefb811a4ba\\">\uc790\ubc14\uc2a4\ud06c\ub9bd\ud2b8 \uac1d\uccb4 \ub525 \ub2e4\uc774\ube0c</h2><a href=\\"https://blog.frontend-almanac.com/js-object-structure\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://blog.frontend-almanac.com/js-object-structure</a><p data-notion-block-id=\\"142d3847-9683-401a-b28a-055e59e65461\\"><b>\uc2ec\uc724\uc12d</b>: \uac1d\uccb4\uc758 \ub0b4\ubd80 \uad6c\uc870\ub97c \uc54e\uacfc \ub3d9\uc2dc\uc5d0 \ud788\ub4e0 \ud074\ub798\uc2a4\uc5d0 \uc9d1\uc911\ud558\uc5ec \ub0b4\ubd80\uc5d0\uc11c \uc5b4\ub5bb\uac8c \ub3d9\uc791\ud558\ub294\uc9c0\ub97c \uc54c\ub824\uc8fc\uace0 \uc788\uc2b5\ub2c8\ub2e4. \uc774\uc640 \uad00\ub828\ub41c <a href=\\"https://ones-to-watch.ethansup.net/news/post/8b8e4348-60f9-477e-9892-e7dfdf611fe0#b0fa8093-7010-49bd-9e12-b95e81fcacef\\">\uc800\ubc88 \uae00</a>\uc744 \ubcf4\uba74 \uc5b4\ub5bb\uac8c \uc2e4\uc81c \ud504\ub85c\uc81d\ud2b8\uc5d0\uc11c \uc5b4\ub5bb\uac8c \uc801\uc6a9\ud560\uc9c0\ub97c \uc0dd\uac01\ud574\ubcfc \uc218 \uc788\uc2b5\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"ecfe89ce-2cee-43c7-be3c-f18300662445\\" id=\\"ecfe89ce-2cee-43c7-be3c-f18300662445\\">\ub2f9\uc2e0\uc740 GraphQL\uc774 \ud544\uc694\ud558\uc9c0 \uc54a\uc2b5\ub2c8\ub2e4.</h2><a href=\\"https://mxstbr.com/thoughts/graphql/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://mxstbr.com/thoughts/graphql/</a><p data-notion-block-id=\\"5bc98715-758c-4cc2-992c-50f0b59f539a\\"><b>\uc2ec\uc724\uc12d</b>: GraphQL\uc740 \ubaa8\ub4e0 \uc0ac\ub78c\uc744 \uc704\ud55c \uae30\uc220\uc774 \uc544\ub2c8\uace0, \ud2b9\uc815 \uc0ac\ub78c\ub9cc\uc744 \uc704\ud55c \uae30\uc220\uc784\uc744 \uac15\uc870\ud558\uace0 \uc788\uc2b5\ub2c8\ub2e4(\uc0ac\uc2e4 \uac70\uc758 \ubaa8\ub4e0 \uae30\uc220\uc774 \uadf8\ub807\uc8e0). \ud56d\uc0c1 \uc790\uc2e0\uc5d0\uac8c \ub9de\ub294 <a href=\\"https://fe-developers.kakaoent.com/2023/230112-appropriate-technology/\\">\uc801\uc815 \uae30\uc220\uc744 \uc120\ud0dd</a>\ud558\ub824\uace0 \ud574\uc57c \ud569\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"4327264d-2f0c-4fd5-8fcb-294cd30f95f3\\" id=\\"4327264d-2f0c-4fd5-8fcb-294cd30f95f3\\">Cloudflare\uc758 \ucd9c\uc2dc \uc8fc\uac04</h2><a href=\\"https://blog.cloudflare.com/blazing-fast-development-with-full-stack-frameworks-and-cloudflare\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://blog.cloudflare.com/blazing-fast-development-with-full-stack-frameworks-and-cloudflare</a><a href=\\"https://blog.cloudflare.com/javascript-native-rpc\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://blog.cloudflare.com/javascript-native-rpc</a><p data-notion-block-id=\\"ce274998-25c3-4a67-90d5-7f60cceba929\\">\uc8fc\ub85c \uc4f0\uc774\ub294 \ud504\ub808\uc784\uc6cc\ud06c(Next.js, Nuxt, \u2026.)\uc5d0\uc11c D1, R2\ub4f1 Cloudflare\uc758 \uac1c\ubc1c\uc790 \ud50c\ub7ab\ud3fc\uc5d0 \uc27d\uac8c \uc811\uadfc\ud560 \uc218 \uc788\ub3c4\ub85d \ub9cc\ub4e4\uace0, \uad00\uacc4\ud615 \ub370\uc774\ud130\ubca0\uc774\uc2a4\uc778 D1\uc744 Prisma\ub97c \ud1b5\ud574 \uc0ac\uc6a9\ud560 \uc218 \uc788\ub2e4\ub294 \uac83\uc744 \ubcf4\uc5ec\uc8fc\uc5c8\uc2b5\ub2c8\ub2e4. \uadf8\ub9ac\uace0 RPC \ud638\ucd9c\uc744 \ud1b5\ud574 \ub2e4\ub978 Worker\uc5d0\uac8c \uac1d\uccb4\ub97c \uc804\ub2ec\ud560 \uc218 \uc788\ub294 \ub4f1 \uc5ec\ub7ec \uae30\ub2a5\uc744 \ucd9c\uc2dc\ud588\uc2b5\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"c71f3f8f-e2c1-4742-ac34-0df1bec77e92\\" id=\\"c71f3f8f-e2c1-4742-ac34-0df1bec77e92\\">HTML \uc2a4\ud2b8\ub9ac\ubc0d\uc73c\ub85c \ud074\ub77c\uc774\uc5b8\ud2b8 \ucf54\ub4dc \uc904\uc774\uae30</h2><a href=\\"https://aralroca.com/blog/html-streaming-over-the-wire\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://aralroca.com/blog/html-streaming-over-the-wire</a><p data-notion-block-id=\\"a2e42c2a-963e-4036-87a5-92e728e4a9fa\\">Htmx\uc5d0 \uc601\uac10\uc744 \uc5bb\uc5b4 \ud074\ub77c\uc774\uc5b8\ud2b8\uc5d0\uc11c\uc758 \ub85c\uc9c1\uc744 \uc904\uc5ec\uc11c \uc6f9 \uc131\ub2a5\uc744 \ud558\uace0\uc790 \ud558\ub294 \ub77c\uc774\ube0c\ub7ec\ub9ac\ub97c \uc18c\uac1c\ud558\ub294 \uae00\uc785\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"61aaa1c8-09c6-4d9f-8693-1f36c71f62c9\\" id=\\"61aaa1c8-09c6-4d9f-8693-1f36c71f62c9\\">Flow\ub294 React \uc2dc\uc7a5\uc744 \ucc28\uc9c0\ud560 \uc218 \uc788\uc744\uae4c</h2><a href=\\"https://medium.com/flow-type/announcing-component-syntax-b6c5285660d0\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://medium.com/flow-type/announcing-component-syntax-b6c5285660d0</a><p data-notion-block-id=\\"dc12b4a1-e110-4cc9-a75c-23d075ca889d\\">Flow \uc5b8\uc5b4\uc5d0\uc11c React\uc5d0\uc11c \ud0c0\uc785 \uac80\uc0ac\ub97c \ub354 \uc798\ud560 \uc218 \uc788\ub3c4\ub85d <code>component</code> / <code>hook</code> / <code>render</code> \uc720\ud615\uc744 \ub9cc\ub4e4\uc5c8\uc2b5\ub2c8\ub2e4.</p><p data-notion-block-id=\\"a20c69c5-3657-46e0-8fa5-3739e0164009\\"></p>"}')}}]);